// Original banner artwork for each sector + the alliance signing (1200x420 SVG, flat two-tone style with soft depth).
// Generated by build-react.mjs: written to react/banners/<id>.svg and embedded in the component as data URIs, so they
// render even where outside image hosts are blocked (e.g. the claude.ai artifact sandbox).
// Composition rule: the subject sits in x 330..980 so a phone-width centre crop keeps it; the bottom strip stays quiet for captions.

const RED = '#dc2626';
const W = '#ffffff';
const S100 = '#f1f5f9', S200 = '#e2e8f0', S300 = '#cbd5e1', S400 = '#94a3b8', S500 = '#64748b', S600 = '#475569', S800 = '#1e293b';

const r = (x, y, w, h, fill, extra = '') => `<rect x="${x}" y="${y}" width="${w}" height="${h}" fill="${fill}" ${extra}/>`;
const c = (cx, cy, rad, fill, extra = '') => `<circle cx="${cx}" cy="${cy}" r="${rad}" fill="${fill}" ${extra}/>`;
const p = (d, fill, extra = '') => `<path d="${d}" fill="${fill}" ${extra}/>`;
const grid = (x, y, cols, rows, w, h, gx, gy, fill, extra = '') => {
  let s = '';
  for (let i = 0; i < cols; i++) for (let j = 0; j < rows; j++) s += r(x + i * (w + gx), y + j * (h + gy), w, h, fill, extra);
  return s;
};
const shadow = (cx, rx) => `<ellipse cx="${cx}" cy="336" rx="${rx}" ry="9" fill="#0f172a" opacity="0.08"/>`;

function frame(tintA, tintB, glow, body) {
  let traces = '';
  const pts = [[60, 300], [60, 220], [120, 160], [250, 160]];
  traces += `<polyline points="${pts.map((q) => q.join(',')).join(' ')}" fill="none" stroke="${S400}" stroke-width="2" opacity="0.5"/>`;
  traces += pts.map(([x, y]) => c(x, y, 5, W, `stroke="${S400}" stroke-width="2" opacity="0.7"`)).join('');
  traces += `<polyline points="1140,90 1080,90 1040,50 960,50" fill="none" stroke="${S400}" stroke-width="2" opacity="0.5"/>` + c(960, 50, 5, W, `stroke="${S400}" stroke-width="2"`) + c(1140, 90, 4, RED);
  return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 1200 420" width="1200" height="420" preserveAspectRatio="xMidYMid slice">
<defs>
<linearGradient id="bg" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stop-color="${tintA}"/><stop offset="1" stop-color="${tintB}"/></linearGradient>
<radialGradient id="glow" cx="0.5" cy="0.5" r="0.5"><stop offset="0" stop-color="${glow}" stop-opacity="0.9"/><stop offset="1" stop-color="${glow}" stop-opacity="0"/></radialGradient>
<linearGradient id="gnd" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#ffffff" stop-opacity="0.75"/><stop offset="1" stop-color="#ffffff" stop-opacity="0.95"/></linearGradient>
<pattern id="dots" width="24" height="24" patternUnits="userSpaceOnUse"><circle cx="2" cy="2" r="1.3" fill="${S400}" opacity="0.4"/></pattern>
</defs>
${r(0, 0, 1200, 420, 'url(#bg)')}${r(0, 0, 1200, 420, 'url(#dots)', 'opacity="0.55"')}
${c(660, 190, 260, 'url(#glow)')}
${traces}
${r(0, 336, 1200, 84, 'url(#gnd)')}<path d="M0 336H1200" stroke="${S300}" stroke-width="2"/>
${body}
</svg>`;
}

const card = (x, y, w, h, inner = '') => `<g>${r(x + 4, y + 8, w, h, '#0f172a', 'rx="14" opacity="0.08"')}${r(x, y, w, h, W, `rx="14" stroke="${S200}" stroke-width="2"`)}${inner}</g>`;

function gear(cx, cy, rad, teeth, fill) {
  let d = '';
  const n = teeth * 2;
  for (let i = 0; i < n; i++) {
    const a = (i / n) * Math.PI * 2;
    const rr = i % 2 ? rad * 0.82 : rad;
    d += `${i ? 'L' : 'M'}${(cx + Math.cos(a) * rr).toFixed(1)} ${(cy + Math.sin(a) * rr).toFixed(1)}`;
  }
  return `<path d="${d}Z" fill="${fill}"/>${c(cx, cy, rad * 0.35, W)}`;
}

